"""Scoped DESeq2 credit requires main-route evidence and 49 primary role reviews."""
import hashlib,json,zipfile
from pathlib import Path
from catalog_source_integrity import verify_source
from catalog_fixed_cohort import verify_fixed_cohort
from signac_scan_evidence import unpack
def read(p):return json.loads(p.read_bytes())
def pin(p):return dict(bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest())
def verify(root,data):
    root=Path(root);data=Path(data);folder=root/'docs/literature/deseq2-tools-development';proof=read(folder/'VALIDATION.json');assert proof['status']=='passed-public-DESeq2-main-original-and-native-workflows' and pin(folder/'controls.zip')==proof['archive'] and pin(folder/'WARNINGS.md')==proof['warnings_document'];files=unpack(folder/'controls.zip',proof)
    for name,value in proof['source_pins'].items():
        raw=files['current-source/'+name];assert dict(bytes=len(raw),sha256=hashlib.sha256(raw).hexdigest())==value;verify_source(root,data,name,value['sha256'])
    assert proof['normal_Gradle_executableJar'] and proof['root_dispatch_available'] and proof['only_changed_packaged_entry']==['org/jlinalg/cli/JLinAlgCli.class'] and not proof['scientific_sources_changed_after_parent_validation']
    assert (proof['original_R_fits'],proof['native_main_analyses'],proof['actual_main_capture_verifications'],proof['finite_numeric_values'],proof['nonfinite_kind_values'],proof['maximum_relative_error'])==(4,6,12,35457,665,0)
    for name,value in proof['parents'].items():
        parent=root/'docs/literature'/name;prior=read(parent/'VALIDATION.json');assert pin(parent/'VALIDATION.json')==value['validation'] and pin(parent/'controls.zip')==value['archive']=={k:prior['archive'][k] for k in ['bytes','sha256']}
        for n,v in prior['source_pins'].items():verify_source(root,data,n,v['sha256'])
        with zipfile.ZipFile(parent/'controls.zip') as z:assert len(z.namelist())==len(set(z.namelist()))==prior['archive_members'] and z.testzip() is None
    inference=read(root/'docs/literature/deseq2-inference-development/VALIDATION.json');assert inference['original_runtime_requests']==26 and inference['comparisons']==dict(numeric_values=264436,nonfinite_kind_values=2972,maximum_relative_error=0.0) and inference['typed_contract_tests_normal_Gradle']==inference['typed_contract_tests_per_JVM']==38 and inference['actual_timeout_cleanup'] and inference['clean_installer_forbidden_skipped']
    roles=read(data/'deseq2-role-coverage.json');assert roles['applied'] and (roles['prior_reviews'],roles['unrelated_reviews_preserved'],roles['new_reviews'],roles['total_reviews'],roles['reviewed_roles'],roles['supporting_pointers'])==(832,831,48,880,49,289);assert roles['recovered_named_declarations']==['P082','P088'] and roles['unresolved_P082_exact_role'] and roles['P088_normalization_not_limma_tests'];verify_source(root,data,'tools/literature/reviewed-uses.json',roles['reviews_sha256'])
    reviews=[r for r in read(root/'tools/literature/reviewed-uses.json')['reviews'] if r['tool_id']=='deseq2'];draft=read(root/'tools/literature/deseq2-use-reviews.json');assert len(reviews)==49 and {r['pmcid']:r for r in reviews}=={r['review']['pmcid']:r['review'] for r in draft};papers=read(data/'papers.json');verify_fixed_cohort(root,data,papers)
    for review in reviews:
        paper=next(p for p in papers if p['pmcid']==review['pmcid']);tool=next(t for t in paper['tools'] if t['tool_id']=='deseq2');assert paper['doi']==review['doi'] and all(tool[k]==review[k] for k in ['evidence_paragraph_sha256','use_summary','implementation_scope_note','version_reported_near_name'])
    for field in ['Linux_R_fits_executed','independent_Java_NB_replay','installed_DLL_source_authentication','quantifier_import_pipeline_available','historical_whole_packages_executed','whole_paper_reproduced','biological_accuracy_certified','released','pushed','deployed','whole_goal_complete']:assert proof[field] is False
    artifact=root/proof['artifact']['path']
    if artifact.exists():assert pin(artifact)=={k:proof['artifact'][k] for k in ['bytes','sha256']}
    return proof

def deseq2_metadata(root,data):
    p=verify(root,data)
    return dict(implementation_status='upstream-adapter-validated',implementation_source='src/main/java/org/jlinalg/cli/Deseq2InferenceCli.java',coverage_note='New scoped main DESeq2 integration: native size-factor/count normalization plus exact original1.52.0 inference, shrinkage, VST/rlog and Java-only VERIFY.49 paper records reviewed; historical editions, wrappers and whole pipelines remain separate.',implementation_scope='Main deseq2-normalize accepts native ratio/poscounts normalization; deseq2-tools accepts typed ANALYZE/VERIFY with exact R4.6.1/DESeq2 1.52.0 private runtime. Explicit factors/numeric covariates/interactions, paired designs, Wald/LRT, factor/coefficient/numeric contrasts, threshold tests, filtering/Cooks/alpha options, normal/apeglm/ashr shrinkage, VST/vst/rlog, explicit technical collapse and R_round, supplied size/normalization factors and all-input normalization before keep_genes. No automatic installation, count conversion, tximport/length-offset construction, pseudobulking, wrapper substitution or historical whole-package equivalence.49 reviewed records include recovered P082 unresolved software declaration and P088 normalization before limma-voom. Read DESEQ2_TOOLS.md and examples/deseq2-tools/README.md.',validation_note='Normal Gradle main executable preserves every packaged scientific class/resource from the frozen inference JAR; only dispatcher class changes. Four main original R fits match35,457 finite values and665 nonfinite kinds exactly, six native analyses and12 portable verifications cover Windows Java21/25 and Linux Java21. Parent26 fits match264,436 finite/2,972 nonfinite values,38 typed tests per JVM and normal Gradle, source failures, real skips, timeout cleanup and clean-runtime installation controls retained. First Windows-path Linux harness failure preserved; relative-path fix passed without scientific edits. Actual R fits are Windows-only. VERIFY checks structural consistency and normalization, not independent NB/transform/shrinkage replay, installed DLL authenticity or coordinated fabricated capture authenticity. Historical editions, unknown roles/units and paper pipelines remain explicit.',project_adapter_available=True,canonical_adapter_available=False,development_adapter_cli='deseq2-tools',development_candidate=p['artifact']['path'],development_candidate_sha256=p['artifact']['sha256'],engine_status=dict(native_size_factors='native-subset-validated',original_current_inference='upstream-adapter-validated',historical_whole_packages='not-certified',quantifier_import='separate-pending',independent_Java_NB_replay='not-implemented'))

